#include <stdio.h>

int coins[] = {1, 3, 4};

int min_coins(int amount) {
    if (amount == 0) {
        return 0;
    }
    int best = 1000;
    for (int i = 0; i < 3; i++) {
        if (coins[i] <= amount) {
            int r = min_coins(amount - coins[i]) + 1;
            if (r < best) {
                best = r;
            }
        }
    }
    return best;
}

int main() {
    printf("%d\n", min_coins(18));
    return 0;
}

